/**
 * school-day/1.0.0: one learner's school day, from arrival to dismissal, as the day shell renders it.
 *
 * The only planning source is the Chief of Staff's resolved days (curriculum/program/stem-v1/resolved-days/
 * g{0..12}-day1.json, generated by scripts/cos-stem/build-program.cjs), with each slot's stage from
 * period-matrix.json. Nothing here invents a period, a lesson or a label: bindings, units, labels and orders are
 * shown exactly as resolved. A replacement lesson binds itself in the resolved day when it passes.
 *
 * Presentation-only: nothing here grants access, records completion or writes any academic record.
 */
import type { AgeBand } from "@/lib/learner-experience/types";

export const SCHOOL_DAY_CONTRACT = "school-day/1.0.0";

export type DayBand = "K_2" | "G3_5" | "G6_8" | "G9_12";
export type BlockKind = "ARRIVAL" | "ASSEMBLY" | "PERIOD" | "BREAK" | "LUNCH" | "SUPPORT" | "END_OF_DAY" | "DISMISSAL";
/** The CoS practice continuum (scripts/cos-stem/build-program.cjs CONTINUUM). */
export type Practice = "CONCEPT" | "GUIDED" | "INDEPENDENT" | "EXTENSION" | "REFLECTION";
export type DaySegment = Readonly<{ minutes: number | null; phase: string; practice: Practice; what: string }>;
export type OrderRef = Readonly<{ orderId: string; unitTitle: string | null; performanceTask: string | null }>;
export type LessonBinding = Readonly<{
  kind: "LESSON"; source: "V4_DRAFT" | "SCHOOLDAY_DRAFT" | "FACTORY_LESSON"; key: string; version: string; selection: string;
  packageHash: string; candidateSha256: string | null; title: string | null; provisional: boolean;
  /** Never APPROVED in the rehearsal: every bound lesson is an ungraded pilot draft. */
  officialStatus: "NOT_APPROVED"; studentLabel: string;
  /** The order this lesson fills (FACTORY_LESSON), or the order that will replace this interim lesson. */
  fillsOrder: string | null; replacementOrder: OrderRef | null; requiresAttachment: string | null;
}>;
export type PeriodBinding =
  | LessonBinding
  | Readonly<{ kind: "GAP"; label: string; teacherLed: string | null; order: OrderRef | null }>
  | Readonly<{ kind: "TEACHER_LED"; label: string; activity: string | null }>
  | Readonly<{ kind: "NON_INSTRUCTIONAL" }>;
/** A slot's production stage, exactly as period-matrix.json records it. */
export type SlotStage = Readonly<{ stage: string; note: string | null; g3: string | null; academicReview: string | null; humanSubjectExpert: string | null }>;
export type DayBlock = Readonly<{
  id: string; slot: string; kind: BlockKind; start: string; end: string;
  /** The school's own period name (a Timetable periodLabel) when it is not a CoS slot code. */
  label?: string | null;
  course: string | null; unit: Readonly<{ number: number | null; title: string; performanceTask: string | null }> | null;
  binding: PeriodBinding; segments: readonly DaySegment[]; stage: SlotStage | null;
}>;
export type SchoolDay = Readonly<{
  /** Null only for a pilot day no CoS resolved day matches exactly (then the grade is not shown, never guessed). */
  contract: typeof SCHOOL_DAY_CONTRACT; planId: string; grade: number | null; gradeLabel: string; section: string; band: DayBand; ageBand: AgeBand;
  /** COS_RESOLVED_DAY: the CoS plan itself. PILOT_TIMETABLE: real Timetable periods from T2's resolvePilotDay. */
  source: "COS_RESOLVED_DAY" | "PILOT_TIMETABLE"; timetableMode: string; theme: Readonly<{ title: string; why: string }> | null;
  blocks: readonly DayBlock[];
}>;
type MatrixRow = { grade: number; section: string; slot: string; stage: string; stageNote?: string | null; g3?: string | null; academicReview?: string | null; humanSubjectExpert?: string | null };

export const GRADES = Array.from({ length: 13 }, (_, grade) => grade);
export const gradeLabel = (grade: number) => (grade === 0 ? "K" : String(grade));
/** CoS developmental bands (developmentalBand / order.developmental.band): K-2, 3-5, 6-8, 9-12. */
const BAND_OF: Record<string, DayBand> = { "K-2": "K_2", "3-5": "G3_5", "6-8": "G6_8", "9-12": "G9_12" };
export const bandForGrade = (grade: number): DayBand => (grade <= 2 ? "K_2" : grade <= 5 ? "G3_5" : grade <= 8 ? "G6_8" : "G9_12");
const AGE_BAND: Record<DayBand, AgeBand> = { K_2: "EARLY_PRIMARY", G3_5: "UPPER_PRIMARY", G6_8: "JUNIOR_SECONDARY", G9_12: "SENIOR_SECONDARY" };
export const ageBandForGrade = (grade: number): AgeBand => AGE_BAND[bandForGrade(grade)];

const KIND_OF_SLOT: Record<string, BlockKind> = { ARRIVAL: "ARRIVAL", ASSEMBLY: "ASSEMBLY", BREAK: "BREAK", LUNCH: "LUNCH", SUPPORT: "SUPPORT", END_OF_DAY: "END_OF_DAY", DISMISSAL: "DISMISSAL" };
const kindOf = (slot: string): BlockKind => KIND_OF_SLOT[slot] ?? (/^P\d+$/.test(slot) ? "PERIOD" : (() => { throw Error(`unknown_day_slot:${slot}`); })());
const PRACTICES: readonly Practice[] = ["CONCEPT", "GUIDED", "INDEPENDENT", "EXTENSION", "REFLECTION"];
const LESSON_KINDS = ["V4_DRAFT", "SCHOOLDAY_DRAFT", "FACTORY_LESSON"] as const;
const HASH = /^[a-f0-9]{64}$/, TIME = /^([01]\d|2[0-3]):[0-5]\d$/;
const text = (value: unknown) => (typeof value === "string" && value.trim() ? value.trim() : null);
const orderRef = (raw: any): OrderRef | null => (text(raw?.orderId) ? { orderId: raw.orderId, unitTitle: text(raw.unitTitle), performanceTask: text(raw.performanceTask) } : null);

function bindingOf(raw: any, slot: string): PeriodBinding {
  if ((LESSON_KINDS as readonly string[]).includes(raw?.kind)) {
    const version = raw.kind === "V4_DRAFT" ? "4.0.0-draft.6" : text(raw.version);
    if (!version || !text(raw.key) || raw.selection !== `factory@${version}@${raw.key}` || !HASH.test(raw.packageHash ?? "")) throw Error(`day_binding_invalid:${slot}`);
    if (raw.officialStatus !== "NOT_APPROVED" || !text(raw.studentLabel)) throw Error(`day_binding_status:${slot}`);
    if (raw.kind === "FACTORY_LESSON" && !text(raw.orderId)) throw Error(`day_binding_order:${slot}`);
    return { kind: "LESSON", source: raw.kind, key: raw.key, version, selection: raw.selection, packageHash: raw.packageHash,
      candidateSha256: HASH.test(raw.candidateSha256 ?? "") ? raw.candidateSha256 : null, title: text(raw.title), provisional: Boolean(raw.provisional),
      officialStatus: "NOT_APPROVED", studentLabel: raw.studentLabel.trim(), fillsOrder: text(raw.orderId), replacementOrder: orderRef(raw.replacementOrder),
      requiresAttachment: text(raw.requiresAttachment) ?? (raw.requiresAttachment ? String(raw.requiresAttachment.kind ?? "ATTACHMENT") : null) };
  }
  switch (raw?.kind) {
    case "CONTENT_GAP":
      // CoS rule: a gap carries no lesson text and is labelled "no approved lesson" / "teacher-led" for learners.
      if (!text(raw.studentLabel) || !/no approved lesson|teacher-led/i.test(raw.studentLabel) || "body" in raw || "content" in raw) throw Error(`day_gap_invalid:${slot}`);
      return { kind: "GAP", label: raw.studentLabel.trim(), teacherLed: text(raw.teacherLedFallback), order: orderRef(raw.generationOrder ?? raw.productionOrder) };
    case "TEACHER_LED": return { kind: "TEACHER_LED", label: text(raw.studentLabel) ?? "Teacher-led", activity: text(raw.activity) };
    case "NON_INSTRUCTIONAL": return { kind: "NON_INSTRUCTIONAL" };
    default: throw Error(`day_binding_kind:${slot}`);
  }
}

function unitOf(raw: any, binding: PeriodBinding) {
  const order = binding.kind === "LESSON" ? binding.replacementOrder : binding.kind === "GAP" ? binding.order : null;
  const fromOrder = raw.binding?.generationOrder ?? raw.binding?.replacementOrder ?? raw.binding?.productionOrder;
  const title = text(fromOrder?.unitTitle) ?? order?.unitTitle ?? null;
  return title ? { number: typeof raw.unit === "number" ? raw.unit : null, title, performanceTask: text(fromOrder?.performanceTask) ?? order?.performanceTask ?? null } : null;
}

/** A CoS resolved day (stem-day-plan/1.0.0) plus its period-matrix rows. Rejects anything malformed rather than guessing. */
export function schoolDayFromResolved(plan: any, matrix: readonly MatrixRow[] = []): SchoolDay {
  if (plan?.planVersion !== "stem-day-plan/1.0.0" || !Number.isInteger(plan.grade) || plan.grade < 0 || plan.grade > 12 || !Array.isArray(plan.blocks)) throw Error("day_plan_invalid");
  // Every resolved day states its own band (CoS 4b4f5ecd6); it must agree with the CoS band edges for its grade.
  const band = BAND_OF[plan.developmentalBand];
  if (!band) throw Error(`day_band_missing:${plan.developmentalBand}`);
  if (band !== bandForGrade(plan.grade)) throw Error(`day_band_mismatch:${plan.developmentalBand}`);
  const section = text(plan.section) ?? "A";
  let previousEnd = "00:00";
  const blocks = plan.blocks.map((raw: any, index: number): DayBlock => {
    const slot = String(raw.slot);
    if (!TIME.test(raw.start) || !TIME.test(raw.end) || raw.start >= raw.end || raw.start < previousEnd) throw Error(`day_plan_times:${slot}`);
    previousEnd = raw.end;
    const segments = (raw.binding?.sequence ?? []).map((s: any): DaySegment => {
      if (!PRACTICES.includes(s.practice) || !text(s.what)) throw Error(`day_segment_invalid:${slot}`);
      return { minutes: typeof s.minutes === "number" ? s.minutes : null, phase: String(s.phase), practice: s.practice, what: s.what.trim() };
    });
    const binding = bindingOf(raw.binding, slot);
    const row = matrix.find((r) => r.grade === plan.grade && r.section === section && r.slot === slot);
    return { id: `${plan.planId}:${index}:${slot}`, slot, kind: kindOf(slot), start: raw.start, end: raw.end, course: text(raw.course),
      unit: unitOf(raw, binding), binding, segments,
      stage: row ? { stage: row.stage, note: text(row.stageNote), g3: text(row.g3), academicReview: text(row.academicReview), humanSubjectExpert: text(row.humanSubjectExpert) } : null };
  });
  return { contract: SCHOOL_DAY_CONTRACT, planId: String(plan.planId), grade: plan.grade, gradeLabel: gradeLabel(plan.grade), section, band, ageBand: AGE_BAND[band],
    source: "COS_RESOLVED_DAY", timetableMode: String(plan.timetableMode),
    theme: plan.dayTheme ? { title: String(plan.dayTheme.title), why: String(plan.dayTheme.why) } : null, blocks };
}

const minutes = (hhmm: string) => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));
/** The block running at a time of day, the next one after it, and where the day is. */
export function blockAt(day: SchoolDay, hhmm: string) {
  const at = minutes(hhmm);
  const index = day.blocks.findIndex((b) => minutes(b.start) <= at && at < minutes(b.end));
  const nextIndex = index >= 0 ? index + 1 : day.blocks.findIndex((b) => minutes(b.start) > at);
  return {
    current: index >= 0 ? day.blocks[index] : null,
    next: nextIndex >= 0 && nextIndex < day.blocks.length ? day.blocks[nextIndex] : null,
    phase: index >= 0 ? "IN_DAY" as const : at < minutes(day.blocks[0].start) ? "BEFORE_SCHOOL" as const : "AFTER_SCHOOL" as const,
  };
}

/** Counts for the summaries. Teaching periods plus support and end of day, reported exactly as bound. */
export function dayCoverage(day: SchoolDay) {
  const periods = day.blocks.filter((b) => b.kind === "PERIOD" || b.kind === "SUPPORT" || b.kind === "END_OF_DAY");
  return { periods: periods.length, lessons: periods.filter((b) => b.binding.kind === "LESSON").length,
    gaps: periods.filter((b) => b.binding.kind === "GAP").length, teacherLed: periods.filter((b) => b.binding.kind === "TEACHER_LED").length };
}

/** A course code as a learner reads it. */
export function courseName(course: string | null) {
  const names: Record<string, string> = { MATH: "Mathematics", SCIENCE: "Science", ENGLISH: "English", CIVICS: "Civics", SOCIAL_STUDIES: "Social Studies",
    COMPUTING: "Computing", COMPUTER_SCIENCE: "Computing", LITERACY: "Literacy", ARTS: "Arts", PE: "Physical Education", CAREER: "Careers", ENGINEERING: "Engineering", BIOLOGY: "Biology", CHEMISTRY: "Chemistry", PHYSICS: "Physics", ARTS_PE: "Arts and PE", HISTORY_GEOGRAPHY: "History and Geography" };
  return course ? names[course] ?? course.replaceAll("_", " ").toLowerCase() : null;
}
